//! Offline projection of the frozen source `AssetFactory.CreateSerialized` dispatch.
//!
//! The fixture is generated by the isolated `ser-factory` source probe. It records
//! changes in the source result across every `ClassIDType`/TPK-version query, so the
//! product can resolve generated classes without running a .NET generator or parser.

use super::asset_factory::FactoryUnityVersion;
use std::collections::BTreeMap;
use std::sync::OnceLock;

const SOURCE_FACTORY_DISPATCH_FIXTURE: &str = include_str!("source_factory_dispatch_fixture.txt");

#[derive(Clone, Debug, Eq, PartialEq)]
enum DispatchOutcome {
    Generated(String),
    Missing,
    Throws(String),
}

impl DispatchOutcome {
    fn parse(value: &str, line: usize) -> Result<Self, SourceFactoryDispatchDataError> {
        if value == "MISSING" {
            return Ok(Self::Missing);
        }
        if let Some(error) = value.strip_prefix("THROW:") {
            if error.is_empty() {
                return Err(data_error(line, "empty source factory exception type"));
            }
            return Ok(Self::Throws(error.to_owned()));
        }
        if value.is_empty() {
            return Err(data_error(line, "empty generated class name"));
        }
        Ok(Self::Generated(value.to_owned()))
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct DispatchEntry {
    bits: u64,
    outcome: DispatchOutcome,
}

#[derive(Debug)]
pub(crate) struct SourceFactoryDispatch {
    histories: BTreeMap<i32, Vec<DispatchEntry>>,
    #[cfg(test)]
    ids: Vec<i32>,
    #[cfg(test)]
    versions: Vec<(FactoryUnityVersion, u64)>,
    #[cfg(test)]
    query_count: usize,
    #[cfg(test)]
    transition_count: usize,
    #[cfg(test)]
    throw_count: usize,
    #[cfg(test)]
    missing_count: usize,
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct SourceFactoryDispatchDataError {
    line: usize,
    message: String,
}

impl std::fmt::Display for SourceFactoryDispatchDataError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(
            f,
            "source factory-dispatch fixture line {}: {}",
            self.line, self.message
        )
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct SourceFactoryLookupError {
    class_id: i32,
    version: String,
    message: String,
}

impl std::fmt::Display for SourceFactoryLookupError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(
            f,
            "source generated-class lookup for class {} at {} failed: {}",
            self.class_id, self.version, self.message
        )
    }
}

impl SourceFactoryDispatch {
    pub(crate) fn embedded() -> &'static Self {
        static DISPATCH: OnceLock<SourceFactoryDispatch> = OnceLock::new();
        DISPATCH.get_or_init(|| {
            Self::parse(SOURCE_FACTORY_DISPATCH_FIXTURE)
                .expect("the embedded source factory-dispatch fixture must be valid")
        })
    }

    fn parse(fixture: &str) -> Result<Self, SourceFactoryDispatchDataError> {
        let mut header: Option<(usize, usize, usize)> = None;
        let mut ids = Vec::new();
        let mut versions = Vec::new();
        let mut histories = BTreeMap::<i32, Vec<DispatchEntry>>::new();
        let mut declared_transitions = None;
        let mut transition_count = 0usize;

        for (line_index, line) in fixture.lines().enumerate() {
            let line_number = line_index + 1;
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            let fields: Vec<&str> = line.split('|').collect();
            match fields.first().copied() {
                Some("FACTORY-DISPATCH") => {
                    if fields.len() != 5 || header.is_some() {
                        return Err(data_error(
                            line_number,
                            "invalid or duplicate FACTORY-DISPATCH header",
                        ));
                    }
                    if fields[1] != "1" {
                        return Err(data_error(
                            line_number,
                            "unsupported factory-dispatch fixture version",
                        ));
                    }
                    header = Some((
                        parse_field(fields[2], line_number, "class ID count")?,
                        parse_field(fields[3], line_number, "query version count")?,
                        parse_field(fields[4], line_number, "source query count")?,
                    ));
                }
                Some("ID") => {
                    if fields.len() != 2 || declared_transitions.is_some() {
                        return Err(data_error(line_number, "invalid ID record"));
                    }
                    let class_id = parse_field(fields[1], line_number, "class ID")?;
                    if ids.last().is_some_and(|previous| *previous >= class_id) {
                        return Err(data_error(
                            line_number,
                            "class IDs are not strictly ordered",
                        ));
                    }
                    ids.push(class_id);
                    histories.insert(class_id, Vec::new());
                }
                Some("VERSION") => {
                    if fields.len() != 3 || declared_transitions.is_some() {
                        return Err(data_error(line_number, "invalid VERSION record"));
                    }
                    let version = FactoryUnityVersion::parse(fields[1])
                        .ok_or_else(|| data_error(line_number, "invalid Unity version"))?;
                    let bits = parse_hex_bits(fields[2], line_number)?;
                    if version.source_order_bits() != Some(bits) {
                        return Err(data_error(
                            line_number,
                            "version text disagrees with source UnityVersion.GetBits",
                        ));
                    }
                    if versions
                        .last()
                        .is_some_and(|(_, previous_bits)| *previous_bits >= bits)
                    {
                        return Err(data_error(
                            line_number,
                            "query versions are not strictly ordered",
                        ));
                    }
                    versions.push((version, bits));
                }
                Some("GEN") => {
                    if fields.len() != 5 || declared_transitions.is_some() {
                        return Err(data_error(line_number, "invalid GEN transition record"));
                    }
                    let class_id: i32 = parse_field(fields[1], line_number, "class ID")?;
                    let version = FactoryUnityVersion::parse(fields[2])
                        .ok_or_else(|| data_error(line_number, "invalid Unity version"))?;
                    let bits = parse_hex_bits(fields[3], line_number)?;
                    if version.source_order_bits() != Some(bits) {
                        return Err(data_error(
                            line_number,
                            "transition version disagrees with source UnityVersion.GetBits",
                        ));
                    }
                    if !versions.iter().any(|(_, known_bits)| *known_bits == bits) {
                        return Err(data_error(
                            line_number,
                            "transition version is absent from the query-version list",
                        ));
                    }
                    let history = histories.get_mut(&class_id).ok_or_else(|| {
                        data_error(line_number, "transition has unknown class ID")
                    })?;
                    if history.last().is_some_and(|previous| previous.bits >= bits) {
                        return Err(data_error(
                            line_number,
                            "class transitions are not strictly ordered",
                        ));
                    }
                    let outcome = DispatchOutcome::parse(fields[4], line_number)?;
                    if history
                        .last()
                        .is_some_and(|previous| previous.outcome == outcome)
                    {
                        return Err(data_error(
                            line_number,
                            "redundant transition does not change the source result",
                        ));
                    }
                    history.push(DispatchEntry { bits, outcome });
                    transition_count += 1;
                }
                Some("TRANSITIONS") => {
                    if fields.len() != 2 || declared_transitions.is_some() {
                        return Err(data_error(line_number, "invalid TRANSITIONS footer"));
                    }
                    declared_transitions =
                        Some(parse_field(fields[1], line_number, "transition count")?);
                }
                _ => return Err(data_error(line_number, "unknown factory-dispatch record")),
            }
        }

        let (expected_ids, expected_versions, expected_queries) =
            header.ok_or_else(|| data_error(1, "missing FACTORY-DISPATCH header"))?;
        let footer =
            declared_transitions.ok_or_else(|| data_error(1, "missing TRANSITIONS footer"))?;
        if ids.len() != expected_ids {
            return Err(data_error(1, "class ID count disagrees with header"));
        }
        if versions.len() != expected_versions {
            return Err(data_error(1, "query version count disagrees with header"));
        }
        if ids.len().checked_mul(versions.len()) != Some(expected_queries) {
            return Err(data_error(
                1,
                "query count disagrees with matrix dimensions",
            ));
        }
        if transition_count != footer {
            return Err(data_error(1, "transition count disagrees with footer"));
        }
        if declared_transitions != Some(transition_count) {
            return Err(data_error(1, "duplicate transition footer"));
        }
        let first_version_bits = versions
            .first()
            .map(|(_, bits)| *bits)
            .ok_or_else(|| data_error(1, "query-version list is empty"))?;
        for class_id in &ids {
            let history = histories
                .get(class_id)
                .ok_or_else(|| data_error(1, "missing class history"))?;
            if history.first().map(|entry| entry.bits) != Some(first_version_bits) {
                return Err(data_error(
                    1,
                    format!("class {class_id} has no initial source dispatch result"),
                ));
            }
        }

        #[cfg(test)]
        let throw_count = histories
            .values()
            .flatten()
            .filter(|entry| matches!(entry.outcome, DispatchOutcome::Throws(_)))
            .count();
        #[cfg(test)]
        let missing_count = histories
            .values()
            .flatten()
            .filter(|entry| matches!(entry.outcome, DispatchOutcome::Missing))
            .count();

        Ok(Self {
            histories,
            #[cfg(test)]
            ids,
            #[cfg(test)]
            versions,
            #[cfg(test)]
            query_count: expected_queries,
            #[cfg(test)]
            transition_count,
            #[cfg(test)]
            throw_count,
            #[cfg(test)]
            missing_count,
        })
    }

    pub(crate) fn generated_class_name(
        &self,
        class_id: i32,
        version: &FactoryUnityVersion,
    ) -> Result<Option<&str>, SourceFactoryLookupError> {
        let bits = version
            .source_order_bits()
            .ok_or_else(|| SourceFactoryLookupError {
                class_id,
                version: version.text.clone(),
                message: "version cannot be ordered by the source UnityVersion rules".to_owned(),
            })?;
        let Some(history) = self.histories.get(&class_id) else {
            // The source-generated factory's default arm returns null for class IDs
            // outside the complete enum/TPK query domain.
            return Ok(None);
        };
        let selected = history.partition_point(|entry| entry.bits <= bits);
        let Some(entry) = selected.checked_sub(1).and_then(|index| history.get(index)) else {
            return Err(SourceFactoryLookupError {
                class_id,
                version: version.text.clone(),
                message: "version precedes the probed source dispatch range".to_owned(),
            });
        };
        match &entry.outcome {
            DispatchOutcome::Generated(name) => Ok(Some(name)),
            DispatchOutcome::Missing => Ok(None),
            DispatchOutcome::Throws(exception) => Err(SourceFactoryLookupError {
                class_id,
                version: version.text.clone(),
                message: format!("source AssetFactory.CreateSerialized throws {exception}"),
            }),
        }
    }

    #[cfg(test)]
    fn source_outcome(&self, class_id: i32, version_bits: u64) -> Option<&DispatchOutcome> {
        self.histories
            .get(&class_id)?
            .iter()
            .take_while(|entry| entry.bits <= version_bits)
            .last()
            .map(|entry| &entry.outcome)
    }
}

fn parse_hex_bits(value: &str, line: usize) -> Result<u64, SourceFactoryDispatchDataError> {
    u64::from_str_radix(value, 16).map_err(|_| data_error(line, "invalid packed Unity version"))
}

fn parse_field<T: std::str::FromStr>(
    value: &str,
    line: usize,
    name: &str,
) -> Result<T, SourceFactoryDispatchDataError> {
    value
        .parse::<T>()
        .map_err(|_| data_error(line, format!("invalid {name}")))
}

fn data_error(line: usize, message: impl Into<String>) -> SourceFactoryDispatchDataError {
    SourceFactoryDispatchDataError {
        line,
        message: message.into(),
    }
}

#[cfg(test)]
mod tests {
    use super::super::source_tpk::SourceTpkDatabase;
    use super::*;
    use crate::processing::asset_factory::ClassLayoutSource;

    #[test]
    fn source_generated_factory_matrix_is_complete_and_retains_non_success_outcomes() {
        let dispatch = SourceFactoryDispatch::embedded();
        assert_eq!(dispatch.ids.len(), 404);
        assert_eq!(dispatch.versions.len(), 1838);
        assert_eq!(dispatch.query_count, 742_552);
        assert_eq!(dispatch.transition_count, 3508);
        assert_eq!(dispatch.throw_count, 37);
        assert_eq!(dispatch.missing_count, 2);
        assert_eq!(dispatch.histories.len(), dispatch.ids.len());
    }

    #[test]
    fn every_source_generated_factory_query_matches_the_rle_source_matrix() {
        let dispatch = SourceFactoryDispatch::embedded();
        let tpk = SourceTpkDatabase::embedded();
        let source_versions = tpk.factory_dispatch_versions();
        assert_eq!(source_versions.len(), dispatch.versions.len());
        for (matrix_version, (expected_version, expected_bits)) in
            dispatch.versions.iter().zip(&source_versions)
        {
            assert_eq!(&matrix_version.0.text, &expected_version.text);
            let matrix_bits = matrix_version.1;
            assert_eq!(matrix_bits, *expected_bits);
            for class_id in &dispatch.ids {
                let expected = dispatch.source_outcome(*class_id, *expected_bits);
                let actual = dispatch.generated_class_name(*class_id, expected_version);
                match expected {
                    Some(DispatchOutcome::Generated(name)) => {
                        assert_eq!(
                            actual.unwrap(),
                            Some(name.as_str()),
                            "class {class_id} at {}",
                            expected_version.text
                        );
                    }
                    Some(DispatchOutcome::Missing) => {
                        assert_eq!(
                            actual.unwrap(),
                            None,
                            "class {class_id} at {}",
                            expected_version.text
                        );
                    }
                    Some(DispatchOutcome::Throws(exception)) => {
                        let error = actual.unwrap_err();
                        assert!(
                            error.to_string().contains(exception),
                            "class {class_id} at {}",
                            expected_version.text
                        );
                    }
                    None => panic!(
                        "source matrix has no class {class_id} result at {}",
                        expected_version.text
                    ),
                }
            }
        }
    }

    #[test]
    fn generated_class_dispatch_tracks_source_version_boundaries_and_abstract_errors() {
        let dispatch = SourceFactoryDispatch::embedded();
        let version = |text| FactoryUnityVersion::parse(text).unwrap();
        assert_eq!(
            dispatch
                .generated_class_name(49, &version("3.5.0f1"))
                .unwrap(),
            Some("TextAsset_3_5")
        );
        assert_eq!(
            dispatch
                .generated_class_name(49, &version("2019.4.40f1"))
                .unwrap(),
            Some("TextAsset_2018_3")
        );
        assert_eq!(
            dispatch
                .generated_class_name(194, &version("5.0.0f4"))
                .unwrap(),
            None
        );
        assert_eq!(
            dispatch
                .generated_class_name(194, &version("2019.4.40f1"))
                .unwrap(),
            None
        );
        let abstract_error = dispatch
            .generated_class_name(0, &version("2019.4.40f1"))
            .unwrap_err();
        assert!(abstract_error
            .to_string()
            .contains("AbstractClassException"));
    }

    #[test]
    fn production_factory_source_uses_versioned_dispatch_and_tpk_fallback() {
        let source = crate::processing::asset_factory::reference_class_layouts();
        let version = FactoryUnityVersion::parse("2019.4.40f1").unwrap();
        assert_eq!(
            source.generated_class_name(49, &version).unwrap(),
            Some("TextAsset_2018_3")
        );
        assert_eq!(source.generated_class_name(194, &version).unwrap(), None);
        assert!(source.tpk_trees(194, &version).unwrap().is_some());
        assert_eq!(
            source.generated_class_name(0, &version).unwrap_err().to_string(),
            "source generated-class lookup for class 0 at 2019.4.40f1 failed: source AssetFactory.CreateSerialized throws AbstractClassException"
        );
    }
}
